-- ScholarBridgeAi — Scholarship rewrite pass 36 (Switzerland)
-- Verified 2026-10-25 against the providers' own pages (cited in source_url).
-- Swiss public universities charge the same low tuition to everyone (CHF 780–860 a semester), which
-- is why the scholarship landscape looks thin: the cantonal and university funds are need-based and
-- reserved for students who already live there. Two of these four rows are real and generous; one is
-- narrower than the old row implied; and one has to be withdrawn on the university's own words.
-- Values are in CHF; amount_usd_value stays 0 for non-USD awards.

-- 726 University of Basel — the Chemistry and Biozentrum master's fellowships at CHF 25,000
UPDATE scholarships SET
  title = 'Basel Excellence Fellowships for Master''s Study',
  description = 'Basel is the clearest illustration of how Swiss university funding actually works, and it is worth separating the two halves. The university-wide answer is no: the University of Basel FAQ says directly that the university does not have scholarships for foreign students, and explains that because funds are limited a student who comes to Basel only for a master''s can generally be supported only up to the amount of the semester fees. The general scholarship fund pays CHF 200 to 600 a person per month and is aimed at the final phase of a degree, while the student body solidarity fund pays CHF 500 to 1,000 a semester; both are hardship instruments for people already enrolled, not entrance awards. The real money sits in departmental fellowships. The Department of Chemistry awards Basel Excellence Fellowships for Master''s Study of CHF 25,000, paid in three instalments across the three semesters as a contribution to the cost of the programme, and every successful applicant is automatically entered into the national Alfred Werner Master''s Student Scholarship competition run by the Swiss Chemical Society, which is worth CHF 30,000 and must be accepted if awarded because it is the larger contribution. The Biozentrum runs a parallel scheme for the MSc in Physics of Life, also CHF 25,000 in three instalments, for a limited number of international candidates with outstanding records. Tuition itself carries no international surcharge at Basel: CHF 850 a semester for Swiss and foreign students alike.',
  requirements = 'Apply for admission to the specific master''s programme that runs the fellowship, since these are departmental awards rather than a university-wide scheme - the MSc Physics of Life at the Biozentrum and the chemistry master''s programmes are the two documented routes. Present an outstanding academic record, because selection is on academic excellence and motivation and the number of fellowships is limited. Submit the programme application by that programme''s own deadline; the fellowships do not run a separate central call with a published date. Note that the university scholarship fund and the solidarity fund are for students already enrolled and in financial difficulty, that they pay only a few hundred francs a month, and that a student coming to Basel solely for a master''s can generally be supported only up to the amount of the semester fees. International students are advised by the university to look for funding in their home country.',
  coverage_type = 'Partial Funding', award_basis = 'fixed', award_amount = 25000, award_currency = 'CHF', award_period = 'total',
  degree_levels = '["Master''s"]', eligible_majors = '["Chemistry","Physics of Life","Biochemistry","Chemical Biology"]', eligible_countries = '["All"]',
  funding_type = 'Departmental merit fellowship',
  tuition_coverage = 'CHF 25,000 paid in three instalments across the three semesters of the master''s programme, as a contribution to the cost of study. Winners of the chemistry fellowship are also entered for the Alfred Werner Master''s Student Scholarship at CHF 30,000, which replaces the fellowship if awarded. Tuition is CHF 850 a semester and is not separately waived.',
  english_requirements = 'The fellowships set no separate English score; the English requirement of the chosen master''s programme applies.',
  required_documents = '["Application to the specific master''s programme","Academic transcripts and degree certificate","Motivation letter","Letters of recommendation","Evidence of research experience where the programme asks for it"]',
  deadline = 'No central fellowship deadline; the deadline is the admission deadline of the programme that awards the fellowship',
  deadline_date = NULL, deadline_type = 'not_published', application_status = 'open',
  expected_deadline_period = 'The fellowships follow the admission rounds of the Chemistry Department and the Biozentrum, with selected candidates commencing in the fall semester.',
  website_url = 'https://chemie.unibas.ch/de/departement/offene-stellen/fellowships-for-master-studies/basel-excellence-fellowships-for-masters-study/',
  source_url = 'https://www.unibas.ch/en/Studies/Advice/Funding/Scholarships/Funding-From-the-University-of-Basel.html',
  application_url = 'https://www.unibas.ch/en/Studies/Advice/Funding/Scholarships.html',
  verification_status = 'verified', source_reliability = 8, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from University of Basel own pages read on 2026-10-25: the Funding From the University of Basel page states that the scholarship funds are awarded primarily as partial scholarships during the final degree phase and range from CHF 200 to 600 per person per month, and that the Solidarity Fund pays CHF 500 to 1,000 per person per semester; the Scholarships page states that parents and the scholarship office in the canton of residence are primarily responsible and advises international students to find out what they are eligible for in their home country; the university scholarship FAQ PDF answers the question whether the university has scholarships for foreign students with Nein, and explains that due to limited funds students who complete only the master in Basel can generally be supported only up to the amount of the semester fees; the Department of Chemistry page describes the Basel Excellence Fellowships for Master Study at CHF 25,000 paid in three instalments, with automatic entry into the Alfred Werner Master Student Scholarship at CHF 30,000 which must be accepted if awarded; the Biozentrum page describes scholarships of CHF 25,000 paid in three instalments for the MSc Physics of Life to a limited number of international candidates; swissuniversities confirms tuition of CHF 850 a semester for domestic and foreign students. CORRECTIONS: the row was titled University of Basel Scholarship, carried an invented USD 675, claimed all three degree levels and gave a 30 April deadline. The university-wide answer for foreign students is no, so the record was not repriced but re-pointed at the departmental fellowships that do exist, and the description now states the no as well as the yes. award_amount carries the published CHF 25,000.'
WHERE id = 726;

-- 738 University of Geneva — the Faculty of Science excellence master's fellowships
UPDATE scholarships SET
  title = 'University of Geneva Excellence Master Fellowships (Faculty of Science)',
  description = 'Geneva pays its science master''s students a real stipend, and the amount is stated on the faculty page rather than buried in a PDF: the Excellence Master Fellowships are worth CHF 10,000 to CHF 15,000 a year, are awarded for one year and are extended for the normal duration of the chosen master''s programme - three or four semesters - provided the fellow passes the first semester. There is no teaching obligation attached. Selection is on academic excellence alone, and the faculty describes the target as exceptional and highly motivated students who want to do a science master''s in one of the disciplines it covers, from astrophysics, biochemistry, biology, chemistry, computer science and mathematics to neuroscience, pharmacy, physics, biomedical sciences, Earth sciences and environmental sciences. The application opens at the beginning of January each year and the next deadline was 28 February 2026 for masters starting on 14 September 2026. Two conditions exclude people: a student who has already begun a master''s at the faculty cannot apply, and the file must be complete, including two recommendation letters sent directly by the professors to the faculty address, because incomplete applications are not considered. The other route at Geneva is the Swiss Government Excellence Scholarship, which is a different instrument entirely: it pays CHF 2,450 a month but targets researchers who already hold a master''s degree, for a 12-month research stay or a doctorate renewable twice, and it is applied for through the Swiss embassy or the national authority in the applicant country.',
  requirements = 'Be admitted, or admissible, to a master''s programme in the University of Geneva Faculty of Science, in one of the disciplines the faculty covers. Hold a bachelor''s degree with an outstanding record and rank among the best of your cohort, since selection is purely on academic excellence and is competitive. Not have already started a master''s programme at the faculty. Submit the online application from the beginning of January, and send the complete file as a single PDF before the deadline, which was 28 February 2026 for the September 2026 intake. Arrange for two professors to send recommendation letters directly to the faculty address, because an incomplete file is not considered. For the separate Swiss Government Excellence Scholarship, hold a master''s degree, be under 35, and apply through the Swiss embassy or national authority in your country for a 12-month research stay or a doctorate.',
  coverage_type = 'Living Stipend', award_basis = 'range', award_amount = 15000, award_currency = 'CHF', award_period = 'year',
  degree_levels = '["Master''s"]', eligible_majors = '["Astrophysics","Biochemistry","Biology","Chemical Biology","Chemistry","Computer Science","Earth Sciences","Environmental Sciences","Mathematics","Neuroscience","Pharmacy","Physics","Biomedical Sciences"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based excellence fellowship',
  tuition_coverage = 'CHF 10,000 to CHF 15,000 a year as a stipend with no teaching obligation, awarded for one year and extended for the three or four semesters of the programme if the first semester is passed. It is a living stipend and does not separately waive tuition.',
  english_requirements = 'The fellowship sets no separate English score, but the faculty asks for English proficiency evidence such as TOEFL or IELTS with the application.',
  required_documents = '["Online fellowship application through the Faculty of Science","Bachelor degree certificate and transcripts","Motivation letter describing scientific interests","Two recommendation letters sent directly by the professors","English proficiency evidence such as TOEFL or IELTS","Admission application for the chosen master''s programme"]',
  deadline = '28 February for a September start; the round for September 2026 closed on 28 February 2026',
  deadline_date = '2027-02-28', deadline_type = 'annual', application_status = 'upcoming',
  website_url = 'https://www.unige.ch/sciences/enseignements/formations/masters/excellencemasterfellowships',
  source_url = 'https://www.unige.ch/sciences/enseignements/formations/masters/excellencemasterfellowships',
  application_url = 'https://www.unige.ch/sciences/enseignements/formations/masters/excellencemasterfellowships',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two University of Geneva own pages read on 2026-10-25: the Faculty of Science excellence fellowships page states that the fellowship consists of CHF 10,000 to CHF 15,000 per year, that it is allocated for one year and extended for the normal duration of the chosen master programme of three or four semesters if the candidate is successful at the end of the first semester, that applications are made online from the beginning of January with the next deadline of 28 February 2026 for masters starting 14 September 2026, that selection is based on excellence, that students who have already started a master at the faculty cannot apply, and that two recommendation letters must be sent directly by the professors; the UNIGE Swiss Confederation excellence scholarships page describes the federal scheme as awarding CHF 2,450 a month for a 12-month research stay or for a doctorate renewable twice, for applicants under 35 residing abroad, with the dossier submitted to the national authority or Swiss diplomatic body; the same page notes that the federal offer is aimed at young researchers who have completed a master''s degree and at artists holding a bachelor. CORRECTIONS: the row was titled University of Geneva Excellence Scholarships, carried an absurd USD 488, claimed all three degree levels and gave a 30 April and 30 November deadline. The real award is CHF 10,000 to CHF 15,000 a year at master level with a 28 February deadline, and it is restricted to the Faculty of Science. award_amount carries the published upper figure of CHF 15,000.'
WHERE id = 738;

-- 743 University of Lausanne — the UNIL Master's Grants, one of the best-value awards in the catalogue
UPDATE scholarships SET
  title = 'UNIL Master''s Grants',
  description = 'Lausanne runs one of the most straightforwardly useful awards in this catalogue and it is open to every nationality. The UNIL Master''s Grants pay CHF 1,600 a month from 15 September to 15 July, which is ten payments a year, for the minimum statutory duration of the chosen master''s programme - usually three or four semesters - and the grant continues unless the student fails definitively after the first year. Over a two-year master''s that is about CHF 32,000. Recipients are also exempt from the fixed course registration fees, with the exception of the CHF 80 payable each semester. The mechanics save a step: the grant application is also the application for admission to the master''s programme, so there is no separate admission file, and everything goes through one online portal by 1 November of the year before the intended start - the current round closes on 1 November 2026 for the 2027-28 academic year. The application costs a non-refundable CHF 200 and the file has to be complete, with certified diplomas and transcripts and recommendation letters sent separately, because incomplete applications are not considered. Three conditions exclude people: you need a foreign university degree that UNIL accepts as equivalent to a bachelor''s, you must not have been registered at UNIL before, and you need the required language level in the language of instruction, which the university states as C1. Around ten grants are awarded each year, so the competition is real, and the university itself warns that the sum is not enough to live on in Switzerland.',
  requirements = 'Hold a foreign university degree that UNIL considers equivalent to a bachelor''s degree before the master''s programme starts. Have an outstanding academic record, since the grants are awarded competitively on excellence. Meet the admission conditions of the chosen UNIL master''s programme and demonstrate the required language level in the language of instruction, which UNIL states as C1 in French or English. Not have been registered at UNIL previously. Register and submit the application online by 1 November of the year before the intended start, which is 1 November 2026 for a 2027-28 start, and pay the non-refundable CHF 200 administrative fee. Upload the complete PDF file with certified diplomas and transcripts, a CV, a cover letter and language evidence, and have the recommendation letters sent separately, since applications sent by email or incomplete applications are not considered.',
  coverage_type = 'Living Stipend', award_basis = 'fixed', award_amount = 1600, award_currency = 'CHF', award_period = 'month',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based monthly grant with tuition exemption',
  tuition_coverage = 'CHF 1,600 a month for ten months a year from 15 September to 15 July, for the minimum statutory duration of the programme, so about CHF 32,000 over a two-year master''s, plus exemption from the fixed course registration fees except the CHF 80 per semester. UNIL states that the amount is not sufficient to live on in Switzerland.',
  english_requirements = 'Applicants must demonstrate the required level in the language of instruction, which UNIL states as C1 in French or English depending on the programme.',
  required_documents = '["Online registration and application through the UNIL portal","Complete PDF application file","Certified diplomas and university transcripts","CV and cover letter","Language proficiency evidence (IELTS or TOEFL or French equivalent)","Recommendation letters sent separately by email","Proof of payment of the CHF 200 administrative fee"]',
  deadline = '1 November 2026 for a start in the 2027-28 academic year',
  deadline_date = '2026-11-01', deadline_type = 'fixed', application_status = 'open',
  website_url = 'https://www.unil.ch/unil/en/home/menuinst/etudier/mobilite-et-echange/etudiantes-et-etudiants-internationaux/etudiantes-internationaux-reguliers/bourse-de-master.html',
  source_url = 'https://www.unil.ch/unil/en/home/menuinst/etudier/mobilite-et-echange/etudiantes-et-etudiants-internationaux/etudiantes-internationaux-reguliers/bourse-de-master.html',
  application_url = 'https://www.unil.ch/unil/en/home/menuinst/etudier/mobilite-et-echange/etudiantes-et-etudiants-internationaux/etudiantes-internationaux-reguliers/bourse-de-master.html',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the official UNIL Master scholarship page read on 2026-10-25, which states that the grant is awarded for the minimum statutory period of the master programme and amounts to CHF 1,600 per month, paid from 15 September to 15 July over ten months a year for the complete duration of the master of one and a half or two years, with the exception of definitive failure after the first year; the accompanying UNIL conditions reproduced across the official documentation add the exemption from fixed registration fees except the CHF 80 semester fee, the 1 November deadline for the following academic year, the CHF 200 non-refundable administrative fee, the rule that the same application serves as the admission application, the requirement of a foreign university degree equivalent to a bachelor''s, an outstanding academic record and no prior UNIL registration, the C1 language requirement in French or English, the two recommendation letters sent separately, and the warning that the amount is not sufficient to live in Switzerland; the number of grants is about ten a year. CORRECTIONS: the row was titled University of Lausanne UNIL Master''s Grants, which is correct, but carried an absurd USD 325, claimed all three degree levels and gave a 30 April deadline. The real reward is CHF 1,600 a month for ten months a year plus a fee exemption, the deadline is 1 November, and it is master''s level only. amount_usd_value is 0 because the provider publishes in Swiss francs and award_amount carries the published CHF 1,600 monthly figure.'
WHERE id = 743;

-- 770 University of Zurich — retired: UZH states it has no scholarship pool for international master's students
UPDATE scholarships SET
  title = 'University of Zurich - no scholarship pool for international master''s students (retired)',
  description = 'The University of Zurich answers this question on its own site and the answer closes the door. Its FAQ for degree-seeking international students states that unfortunately UZH does not have a dedicated scholarship pool for international Master''s students, and its financial support page adds the reason: prospective international students at master''s level can apply for support only if they hold a Swiss bachelor''s degree, and international students cannot apply at bachelor''s level until they have completed the first year. The university''s own excellence scholarships, launched as a three-year pilot in 2022 with twenty awards of CHF 10,000 a semester worth up to CHF 40,000, were open only to students already at UZH. The Swiss Government Excellence Scholarship, which does operate at Zurich, is not a master''s scholarship: it pays CHF 1,920 a month for doctoral and research scholarships and CHF 3,500 for postdoctoral ones, and targets researchers who already hold a master''s degree, applied for through the national authority or Swiss embassy. Tuition at UZH is genuinely low - CHF 780 a semester plus a CHF 100 surcharge for international master''s students and CHF 59 of contributions - but low tuition is not a scholarship. The old record claimed a USD 910 University of Zurich Scholarship with an April and November deadline; no such award exists, so the row is withdrawn.',
  coverage_type = 'Unspecified', award_basis = 'variable', award_amount = NULL, award_currency = 'CHF', amount_usd_value = 0,
  deadline = 'Not published', deadline_date = NULL, deadline_type = 'not_published',
  website_url = 'https://www.int.uzh.ch/en/in/degree-seeking-students/faq_international_ma.html',
  source_url = 'https://www.studienfinanzierung.uzh.ch/en/financial_support.html',
  verification_status = 'verified', source_reliability = 9, is_active = false,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Retired after reading three University of Zurich own pages on 2026-10-25: the FAQ for degree-seeking international students at int.uzh.ch answers the question whether there are UZH scholarships for international master students with the statement that UZH does not have a dedicated scholarship pool for international master students; the financial support page at studienfinanzierung.uzh.ch states that prospective international students at master level can only apply for support if they have a Swiss bachelor degree and that international students cannot apply for bachelor support until they have completed the first year; the international office FAQ gives the Swiss Government Scholarship amounts of CHF 1,920 a month for doctoral and research scholarships and CHF 3,500 for postdoctoral scholarships; the UZH news article on excellence scholarships describes the 2022 three-year pilot of twenty awards of CHF 10,000 a semester, up to CHF 40,000, open only to UZH students. The retired row claimed a USD 910 University of Zurich Scholarship with an April and November deadline and all three degree levels. No such award is published, so the row is deactivated rather than repriced, and the quotes are kept so the claim can be checked.'
WHERE id = 770;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = v.avail, funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = v.tuition, covers_living_expenses = v.living, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (135, 'Basel Excellence Fellowships for Master''s Study', 'Yes', 'Departmental merit fellowship', 'CHF 25,000 paid in three instalments; the Alfred Werner award at CHF 30,000 replaces it if won', false, true, 'Departmental rather than university-wide: the Chemistry Department and the Biozentrum each award CHF 25,000 across three semesters to a limited number of international candidates with outstanding records. The University of Basel FAQ states that the university does not have scholarships for foreign students. Tuition is CHF 850 a semester for everyone.', 'https://chemie.unibas.ch/de/departement/offene-stellen/fellowships-for-master-studies/basel-excellence-fellowships-for-masters-study/'),
  (167, 'University of Geneva Excellence Master Fellowships (Faculty of Science)', 'Yes', 'Merit-based excellence fellowship', 'CHF 10,000 to CHF 15,000 a year, extended for the full programme', false, true, 'Faculty of Science master''s programmes only. Selection on academic excellence, no teaching obligation. Applications open at the beginning of January and close on 28 February for a September start. Students who have already begun a master at the faculty are excluded, and two recommendation letters must be sent directly by the professors.', 'https://www.unige.ch/sciences/enseignements/formations/masters/excellencemasterfellowships'),
  (112, 'UNIL Master''s Grants', 'Yes', 'Merit-based monthly grant with tuition exemption', 'CHF 1,600 a month for ten months a year, about CHF 32,000 over two years, plus fee exemption', true, true, 'Open to all nationalities. Requires a foreign degree equivalent to a bachelor''s, an outstanding record, C1 in the language of instruction and no prior UNIL registration. One application covers both admission and the grant. Deadline 1 November 2026; CHF 200 non-refundable fee. About ten grants a year and the university warns the sum is not enough to live on.', 'https://www.unil.ch/unil/en/home/menuinst/etudier/mobilite-et-echange/etudiantes-et-etudiants-internationaux/etudiantes-internationaux-reguliers/bourse-de-master.html'),
  (66, 'University of Zurich - no scholarship pool for international master''s students', 'No', 'Not applicable', 'None published for international master''s students', false, false, 'UZH states that it does not have a dedicated scholarship pool for international master''s students and that master-level support is limited to those holding a Swiss bachelor''s degree. The Swiss Government Excellence Scholarship at UZH is for doctoral and postdoctoral researchers who already hold a master''s, not for master''s study.', 'https://www.int.uzh.ch/en/in/degree-seeking-students/faq_international_ma.html')
) AS v(id, name, avail, ftype, mx, tuition, living, elig, url)
WHERE u.id = v.id;
